tool_input.new_string:
.app-wrapper {
  height: 100%;
  /* 父级 .app-viewport 仅 min-height:100vh（高度为 auto），
     直接给 height:100% 无法解析，会塌缩为内容高度，导致首页下方留白；
     以 min-height:100vh 撑满视口，首页底部待办/公告方能填满。
     避免重复占高，配合 box-sizing。 */
  min-height: 100vh;
  box-sizing: border-box;
  width: 100%;
  min-width: 992px; /* 设置最小宽度 992px，小于此宽度会出现横向滚动条 */
  display: flex;
  flex-direction: column;
  overflow-x: auto; /* 允许横向滚动 */
}

