const { chromium } = require('./node_modules/playwright')
const path = require('path')
;(async () => {
  const fs=require('fs'); fs.mkdirSync(path.resolve(__dirname,'verify-shots'),{recursive:true})
  const browser = await chromium.launch({ channel: 'msedge' })
  const ctx = await browser.newContext({ viewport: { width: 1920, height: 953 } })
  const page = await ctx.newPage()
  await page.goto('http://127.0.0.1:8092/#/login', { waitUntil:'networkidle', timeout:30000 })
  await page.waitForTimeout(1200)
  const t=page.locator('.el-tabs__item:has-text("账号密码登录")'); if(await t.count()){const c=await t.first().getAttribute('class'); if(!c||!c.includes('is-active')){await t.first().click();await page.waitForTimeout(300)}}
  await page.locator('input[placeholder="请输入用户名"]').first().fill('91320505MA1X866218')
  await page.locator('input[placeholder="请输入用户密码"]').first().fill('ZS0001Aa!')
  await page.locator('.login-button').first().click()
  await page.waitForTimeout(7000)
  await page.waitForTimeout(2500)
  await page.screenshot({ path: path.resolve(__dirname,'verify-shots/developer-final.png') })
  const geo = await page.evaluate(()=>{const g=(s)=>{const el=document.querySelector(s);if(!el)return null;const r=el.getBoundingClientRect();return{top:Math.round(r.top),bottom:Math.round(r.bottom),h:Math.round(r.height)}};return{vh:innerHeight,todo:g('.sidebar-todo'),notice:g('.sidebar-notice'),layout:g('.home-layout-sidebar'),url:location.hash}})
  console.log(JSON.stringify(geo))
  await browser.close()
})()
